class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.navRef = React.createRef();
  }
  renderVals() {
    return {
      navRef: this.navRef,
      showReadingTime: this.props.showReadingTime ?? true,
      showBackToTop: this.props.showBackToTop ?? true,
      tocOrder: (this.props.tocPosition ?? "Left") === "Right" ? 1 : -1
    };
  }
  componentDidMount() {
    const nav = this.navRef.current;
    if (!nav) return;
    const links = Array.from(nav.querySelectorAll("a[href^='#']"));
    const byId = {};
    links.forEach(a => { byId[a.getAttribute("href").slice(1)] = a; });
    const setActive = (id) => {
      links.forEach(a => {
        const on = a === byId[id];
        a.style.borderLeftColor = on ? "#C1882C" : "transparent";
        a.style.color = on ? "#2A2118" : "#514A3F";
        a.style.background = on ? "#EFEADC" : "transparent";
        a.style.fontWeight = on ? "600" : "400";
      });
      const a = byId[id];
      if (a && nav.scrollHeight > nav.clientHeight) {
        const top = a.offsetTop, bot = top + a.offsetHeight;
        if (top < nav.scrollTop) nav.scrollTop = top - 8;
        else if (bot > nav.scrollTop + nav.clientHeight) nav.scrollTop = bot - nav.clientHeight + 8;
      }
    };
    const secs = Array.from(document.querySelectorAll("[data-sec]"));
    if (!secs.length) return;
    let current = null;
    const pick = () => {
      let id = secs[0].getAttribute("data-sec");
      for (const s of secs) {
        if (s.getBoundingClientRect().top <= 120) id = s.getAttribute("data-sec");
        else break;
      }
      if (id !== current) { current = id; setActive(id); }
    };
    let lastOffset = null, lastWidth = null;
    const poll = () => {
      const se = document.scrollingElement || document.documentElement;
      const offset = window.scrollY || se.scrollTop || 0;
      const width = window.innerWidth;
      if (offset !== lastOffset || width !== lastWidth) {
        lastOffset = offset; lastWidth = width;
        pick();
      }
    };
    // Guaranteed path: timers survive embeddings where rAF / scroll events / IO are suspended.
    this._poll = setInterval(poll, 150);
    // Opportunistic fast paths for real browsers.
    this._onScroll = poll;
    window.addEventListener("scroll", poll, { passive: true, capture: true });
    window.addEventListener("resize", poll, { passive: true });
    const tick = () => { poll(); this._raf = requestAnimationFrame(tick); };
    this._raf = requestAnimationFrame(tick);
    pick();
  }
  componentWillUnmount() {
    if (this._poll) clearInterval(this._poll);
    if (this._raf) cancelAnimationFrame(this._raf);
    window.removeEventListener("scroll", this._onScroll, { capture: true });
    window.removeEventListener("resize", this._onScroll);
  }
}
